{
  "bioavailability_prediction": "low",
  "confidence": "moderate",
  "revision_action": "strengthen",
  "supportive_card_ids": ["C04","C06","C12","C23","C64","C171","C193","C204","C233","C264","C271","C279","C281","C288","C292"],
  "contradictory_card_ids": [],
  "prediction_basis_card_ids": ["C04","C06","C12","C23","C64","C171","C193","C204","C233","C264","C271","C279","C281","C288","C292"],
  "claims": [
    {
      "claim": "L1 lopinavir records consistently report low or poor human oral bioavailability, attributed to poor solubility, poor permeability, and CYP3A4/P-gp first-pass elimination.",
      "card_ids": ["C04","C06","C12","C23"]
    },
    {
      "claim": "L2 rat data give lopinavir absolute oral bioavailability of 5% versus IV, and formulation strategies were needed to raise exposure, implying low baseline F.",
      "card_ids": ["C64"]
    },
    {
      "claim": "L4 solubility/dissolution records for lopinavir show crystalline solubility near 3 µg/mL across pH and bulk dissolution of only 12% in 2 hours, supporting a poor absorption component.",
      "card_ids": ["C171","C193"]
    },
    {
      "claim": "L5 gut-wall records show related peptidomimetic protease inhibitors are P-gp/BCRP and/or intestinal CYP3A substrates, with elevated efflux ratios and reduced absorptive permeability, supporting presystemic loss.",
      "card_ids": ["C204","C233"]
    },
    {
      "claim": "L6 hepatic-clearance records for related protease inhibitors and thiazole-containing peptidomimetics show measurable to substantial intrinsic clearance in human/rat liver microsomes or hepatocytes (e.g., darunavir 10.5 µL/min/10^6 hepatocytes; saquinavir 73.8–112 µL/min/mg; indinavir 16.5–80.4 µL/min/mg; compound 7 345 µL/min/mg with 3% remaining; compound 1 ~260 µL/min/mg), supporting hepatic first-pass metabolism.",
      "card_ids": ["C264","C271","C279","C281","C288","C292"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "hepatic_clearance_metabolic_stability",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C264","C271","C279","C281","C288","C292"]
    }
  ],
  "evidence_gaps": [
    "No direct oral bioavailability measurement exists for the query molecule.",
    "L6 hepatic-clearance records are for reference molecules, not the query itself.",
    "Species differences (rat vs human) and assay-system differences limit quantitative transfer.",
    "Structural differences from lopinavir and the L6 reference molecules (thiazole, urea, carbamate) may alter metabolism and permeability.",
    "No query-specific CYP phenotyping or metabolic-stability experiment is available."
  ],
  "decision_summary": "Predicted low is strengthened. L6 hepatic-clearance and metabolic-stability records for related protease inhibitors and thiazole-containing peptidomimetics show substantial intrinsic clearance, supporting hepatic first-pass loss; combined with L1 low-F lopinavir records, L2 rat absolute F of 5%, L4 poor solubility/dissolution, and L5 P-gp/CYP3A gut-wall evidence, the threshold-relevant evidence coherently supports F below 20%. No L6 record contradicts the low prediction."
}

